   "code": "// Outbox of pending mutations with ordered, idempotent replay\nconst db = await openDB('app', 1, { upgrade(d) { d.createObjectStore('tasks', { keyPath: 'id' }); d.createObjectStore('outbox', { keyPath: 'seq', autoIncrement: true }); } });\n\nasync function updateTask(task) {\n  const tx = db.transaction(['tasks', 'outbox'], 'readwrite');\n  await tx.objectStore('tasks').put(task);                               // UI reads this immediately\n  await tx.objectStore('outbox').add({ op: 'updateTask', task, key: crypto.randomUUID() });\n  await tx.done;\n  flush();\n}\n\nlet flushing = false;\nasync function flush() {\n  if (flushing || !navigator.onLine) return;\n  flushing = true;\n  try {\n    for (;;) {\n      const next = await db.transaction('outbox').store.openCursor();\n      if (!next) break;\n      const m = next.value;\n      const res = await fetch('/api/mutations', { method: 'POST', headers: { 'Idempotency-Key': m.key, 'Content-Type': 'application/json' }, body: JSON.stringify(m) });\n      if (res.status >= 500) break;                                        // try again later, keep order\n      await db.delete('outbox', m.seq);                                    // 2xx, or 4xx we cannot fix\n    }\n  } finally { flushing = false; }\n}\naddEventListener('online', flush);",
